@extends('layouts.app')@section('content')<h1>Kalender</h1><div class="card" id="calendar"></div><link href="https://cdn.jsdelivr.net/npm/fullcalendar@6.1.15/index.global.min.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/fullcalendar@6.1.15/index.global.min.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{let cal=new FullCalendar.Calendar(document.getElementById('calendar'),{initialView:'dayGridMonth',editable:true,locale:'de',events:'{{ route('calendar.events') }}',eventClick:i=>{if(i.event.extendedProps.url) location=i.event.extendedProps.url},eventDrop:save,eventResize:save});function save(i){fetch('{{ url('/calendar/campaigns') }}/'+i.event.id,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({start_date:i.event.startStr.substring(0,10),end_date:i.event.endStr?i.event.endStr.substring(0,10):null})}).then(r=>{if(!r.ok)i.revert()})}cal.render();});</script>@endsection
